SELECT cache.group_jid AS groupJid, cache.subject, cache.announce_only AS announce, cache.snapshot_at AS snapshotAt, cache.observer_account_id AS observerAccountId, state.participant_jid AS participantJid, state.phone, state.is_admin AS admin, state.is_owner AS owner, state.role, state.is_in_group AS inGroup, state.state_source AS stateSource, state.state_updated_at AS stateUpdatedAt FROM whatsapp_group_member_cache cache LEFT JOIN whatsapp_group_member_state state ON state.tenant_id = cache.tenant_id AND state.group_jid = cache.group_jid WHERE cache.tenant_id = #{tenantId} AND cache.group_jid IN
#{groupJid}
ORDER BY cache.group_jid ASC, state.participant_jid ASC

SELECT snapshot_version
FROM whatsapp_group_member_cache
WHERE tenant_id = #{tenantId}
  AND group_jid = #{groupJid}
FOR UPDATE
